class SmaTrend(Strategy):
    name = "sma_trend"
    LOOKBACK = 50
    warmup_bars = 50

    def on_bar(self, symbol, store):
        window = store.window(symbol, self.timeframe)
        if len(window) < self.warmup_bars:
            return math.nan
        closes = window.closes()
        sma = ta.sma(closes, self.LOOKBACK)
        if not math.isfinite(sma):
            return math.nan
        last_close = closes[-1]
        if last_close > sma:
            return 1.0
        if last_close < sma:
            return -1.0
        return 0.0
